static void die(const char *s){fprintf(stderr,"%s\n",s);exit(1);}
static void want(uint32_t v){uint32_t got=a0_runtime_read(session);if(got!=v){fprintf(stderr,"protocol %u != %u\n",got,v);exit(2);}}
static void send(uint32_t op,uint32_t n,const uint32_t *args){a0_runtime_write(session,op);a0_runtime_write(session,n);for(uint32_t i=0;i<n;i++)a0_runtime_write(session,args[i]);}
static unsigned char *file(const char *p,uint32_t *n){FILE*f=fopen(p,"rb");if(!f)die("open");fseek(f,0,SEEK_END);long z=ftell(f);if(z<0||(uint64_t)z>UINT32_MAX)die("size");rewind(f);unsigned char*b=malloc((size_t)z+1);if(!b)die("malloc");if(fread(b,1,(size_t)z,f)!=(size_t)z)die("read");fclose(f);*n=(uint32_t)z;return b;}
static uint32_t u32(const unsigned char*p){return(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint32_t upload(const unsigned char*p,uint32_t n){if(n==0)return 0;send(1,1,&n);want(0);want(1);uint32_t h=a0_runtime_read(session);for(uint32_t i=0;i<n;){uint32_t k=n-i>128?128:n-i;uint32_t a[131]={h,i,k};for(uint32_t j=0;j<k;j++)a[j+3]=p[i+j];send(3,k+3,a);want(0);want(0);i+=k;}return h;}
static uint32_t hash(const unsigned char*p,uint32_t n){uint32_t h=UINT32_C(2166136261);for(uint32_t i=0;i<n;i++)h=(uint32_t)((uint64_t)(h^p[i])*UINT32_C(16777619));return h;}
static void source_unchanged(uint32_t h,const unsigned char*p,uint32_t n){for(uint32_t i=0;i<n;){uint32_t k=n-i>128?128:n-i;const uint32_t a[]={h,i,k};send(2,3,a);want(0);want(k);for(uint32_t j=0;j<k;j++)want(p[i+j]);i+=k;}}
int main(int argc,char**argv){if(argc!=6)die("source0 source1 cases budget newStatus");uint32_t n[2],cs;unsigned char*s[2]={file(argv[1],&n[0]),file(argv[2],&n[1])};unsigned char*c=file(argv[3],&cs);if(cs%24)die("case frame");const uint32_t count=cs/24,budget=(uint32_t)strtoul(argv[4],NULL,10),newStatus=(uint32_t)strtoul(argv[5],NULL,10);session=a0_arena_create(budget,0);if(!session)die("session");want(0);want(2);want(A0_ARENA_MAGIC);want(1);uint32_t handles[2]={upload(s[0],n[0]),upload(s[1],n[1])};a0_io io,before;memset(&io,0,sizeof io);memcpy(&before,&io,sizeof io);NEW_RESULT make=a0_si_new(&io);if(make.f0!=newStatus||make.f2!=&io)die("new result");HEADER h=make.f1;uint32_t (*records)[5]=calloc((size_t)count+1,sizeof*records);if(!records)die("record allocation");uint32_t unique=0;if(newStatus==0){for(uint32_t i=0;i<count;i++){uint32_t row[6];for(uint32_t j=0;j<6;j++)row[j]=u32(c+i*24+j*4);uint32_t handle=row[0]<2?handles[row[0]]:0;INTERN_RESULT r=a0_si_intern(&io,h,handle,row[1],row[2]);if(r.f0!=row[3]||r.f2!=row[4]||r.f1.f3!=row[5]||r.f3!=&io){fprintf(stderr,"case %u: status %u/%u id %u/%u used %u/%u\n",i,r.f0,row[3],r.f2,row[4],r.f1.f3,row[5]);return 3;}if(r.f0!=0&&memcmp(&r.f1,&h,sizeof h)!=0)die("error published metadata");if(r.f0==0&&row[5]>unique){if(row[4]!=unique||row[0]>=2)die("nonsequential ID");records[unique][0]=handle;records[unique][1]=row[1];records[unique][2]=row[2];records[unique][3]=hash(s[row[0]]+row[1],row[2]);records[unique][4]=unique;unique++;}h=r.f1;if(h.f0.f1!=h.f3*5u||h.f0.f1>h.f0.f2)die("vector metadata");}for(uint32_t i=0;i<unique;i++){uint32_t args[]={h.f0.f0,i*5u,5u};send(2,3,args);want(0);want(5);for(uint32_t j=0;j<5;j++)want(records[i][j]);}}else if(h.f0.f0||h.f0.f1||h.f0.f2||h.f1||h.f2||h.f3)die("failed creation published header");if(memcmp(&io,&before,sizeof io))die("IO struct changed");source_unchanged(handles[0],s[0],n[0]);source_unchanged(handles[1],s[1],n[1]);uint32_t code=0;send(5,1,&code);want(0);want(0);if(!a0_arena_is_complete(session)||a0_arena_allocated_words(session))die("incomplete");a0_arena_destroy(session);free(records);free(c);free(s[0]);free(s[1]);return 0;}
